INSERT INTO `location_spaces` (`id`, `parent_id`, `name`, `category`, `primary_photo`, `primary_photo_thumbnail`, `secondary_photo`, `description`, `first_appearance`) VALUES
(1, 1, 'The Lab (Taskmaster UK)', 'lab', '001_the_lab_taskmaster_uk.jpg', '001_the_lab_taskmaster_uk_thumb.jpg', NULL, 'The lab is an all-white room at the back of the Taskmaster house, with sheets of clear plastic hanging from the walls, and vinyl flooring.|The room is often used for inside tasks which are expected to become messy.|There is typically a plain white table positioned at the centre of the room, where the task brief is presented, but the contents of the room do sometimes vary to accommodate specific tasks.', 'The lab is first seen in the \'<a href=\"/task.php?id=2\">Eat as much watermelon as possible</a>\' task, in the first episode of series 1.'),
(2, 1, 'The Living Room (Taskmaster UK)', 'study', '002_the_living_room_taskmaster_uk.jpg', '002_the_living_room_taskmaster_uk_thumb.jpg', NULL, 'The living room is a large room at the side of the Taskmaster house which varies wildly in appearance from one series to the next, in line with specific themes.|However, fairly permanent features of the room are a table at it\'s centre, with one or more chairs (depending on the task), a sofa to the left-hand side of the room, and a large portrait of Greg on the back wall (the style or theme of which dictates the décor of the rest of the room).|There is also a long fake apothecary cabinet along the left wall (with perhaps just one real drawer in it), and a long fake set of bookcases along the right wall (with occasional real books, when needed).|The living room has a set of double-doors in its external wall which open up into <a href=\"/space.php?id=4\">the garden</a>.|The decor of the room was fairly simple in early series, but has become increasingly busy in more recent years, with many thematically-related props and accessories scattered around and filling almost all of the available wall space.', 'The living room is first seen in the \'<a href=\"/task.php?id=2\">Eat as much watermelon as possible</a>\' task, in the first episode of series 1.'),
(3, 1, 'The Kitchen (Taskmaster UK)', 'kitchen', NULL, NULL, NULL, 'The kitchen is a compact and mostly functional space within the Taskmaster house, mainly used for tasks where food preparation is required.|The kitchen tends to be fully stocked with a variety of food and food-making equipment, and is otherwise fairly un-noteworthy, as a space.', NULL),
(4, 1, 'The Garden (Taskmaster UK)', 'garden', '004_the_garden_taskmaster_uk.jpg', '004_the_garden_taskmaster_uk_thumb.jpg', NULL, 'The garden is an area of lawn which wraps around the side of the Taskmaster house, between <a href=\"/space.php?id=5\">the driveway</a> and <a href=\"/space.php?id=7\">the caravan</a>, and <a href=\"/space.php?id=10\">the stage</a>.|The garden\'s external borders are formed with a combination of wooden panel fencing and tall hedges, with taller net fencing running the length of the garden to catch any errant balls from the adjacent golf course.', 'The garden is first seen in the \'<a href=\"/task.php?id=4\">Empty the bathtub</a>\' task.'),
(5, 1, 'The Driveway (Taskmaster UK)', 'driveway', NULL, NULL, NULL, 'The concrete driveway leads from the gates of the property, down to the front door of the house and adjacent garage and dome.|The show has taken advantage of the sloping nature of the start of the driveway in some tasks involving rolling things.|The flatter part of the driveway, nearer to the house, has been used for outside tasks where a flat, solid ground surface is required.', NULL),
(6, 1, 'The Shed (Taskmaster UK)', 'shed', '006_the_shed_taskmaster_uk.jpg', '006_the_shed_taskmaster_uk_thumb.jpg', NULL, 'The shed is generally primarily a repository for a variety of supplies and equipment that contestants can use as desired to solve tasks.|Series 1 of the show used a different shed than subsequent series.|From series 16, the shed has been relocated from its previous location at the side of the house, to now being located behind <a href=\"/space.php?id=7\">the caravan</a>. Its prior location is now filled by <a href=\"/space.php?id=11\">the hutch</a>.', 'The interior of the shed is first seen in the \'<a href=\"/task.php?id=4\">Empty the bathtub</a>\' task.'),
(7, 1, 'The Caravan (Taskmaster UK)', 'caravan', NULL, NULL, NULL, 'The caravan is parked up at the edge of <a href=\"/space.php?id=5\">the driveway</a> and <a href=\"/space.php?id=4\">the garden</a>, and made its first appearance in series 4.|Since then, its appearance has changed a little, and it is now surrounded by a low perimeter or fake box hedge.|The US-style mailbox outside the caravan is sometimes used to present the task brief to the contestants, but they more often receive their instructions at the table within the caravan.', NULL),
(8, 1, 'The Garage (Taskmaster UK)', NULL, NULL, NULL, NULL, 'The garage is a standalone structure, immediately adjacent to the Taskmaster house, and accessible from <a href=\"/space.php?id=5\">the driveway</a>.|It did not make many appearances as a location for tasks until series 10, so was presumably used primarily for storage before then.|The contents of the garage tend to be adapted purely for the purposes of each task, with no obvious recurring fixtures.', NULL),
(9, 1, 'The Dome (Taskmaster UK)', 'dome', NULL, NULL, NULL, 'The dome is a large clear plastic geodesic dome with a wooden decking floor, positioned to the right-hand side of the front door of the Taskmaster house, adjacent to <a href=\"/space.php?id=5\">the driveway</a> and <a href=\"/space.php?id=4\">the garden</a>, and opposite <a href=\"/space.php?id=7\">the caravan</a>.', NULL),
(10, 1, 'The Stage (Taskmaster UK)', NULL, NULL, NULL, NULL, 'The stage is an area of decking which has been added to the side of the Taskmaster house, adjacent to <a href=\"/space.php?id=11\">the hutch</a> (and, previously, <a href=\"/space.php?id=6\">the shed</a>).|Previously, this part of the garden was partially paved.|The addition of the stage differentiates the space from the rest of <a href=\"/space.php?id=4\">the garden</a>.', NULL),
(11, 1, 'The Hutch (Taskmaster UK)', NULL, NULL, NULL, NULL, 'The hutch is a customised LandPod structure, located in <a href=\"/space.php?id=4\">the garden</a>, at the side of the Taskmaster house, in the space previously occupied by <a href=\"/space.php?id=6\">the shed</a>.|The hutch contains a table and seating.', NULL),
(12, 1, 'The Hallway (Taskmaster UK)', 'hallway', NULL, NULL, NULL, 'The hallway leads from the front door of the Taskmaster house, all the way to the door of the lab, passing the toilet, the living room, and the kitchen.', NULL),
(13, 1, 'The Toilet (Taskmaster UK)', 'bathroom', NULL, NULL, NULL, 'The toilet is a small bathroom just off the hallway in the Taskmaster house, just before the living room.', NULL),
(14, 29, 'The Lab (Kongen Befaler Season 1)', 'lab', NULL, NULL, NULL, 'The lab is a room in the Kongen Befaler house which has sheets of clear plastic hanging from the walls.|The room is often used for inside tasks which are expected to become messy.|There is typically a stainless steel table positioned at the centre of the room, where the task brief is presented, but the contents of the room do sometimes vary to accommodate specific tasks.', NULL),
