(42, 32, 'The Study (Stormester Season 1)', 'study', '042_the_study_stormester_i.jpg', '042_the_study_stormester_i_thumb.jpg', NULL, 'The study is an attractively furnished room in the house, with a solid wooden desk at its centre, where the contestants usually find the task brief and any necessary props for the task.|The wall behind the desk prominently features a portrait of Lasse, and the Stormester trophy.', 'The study is first seen in the \'<a href=\"/space.php?id=42\">Throw a teabag into a mug</a>\' task , in the first episode of season 1.'),
(43, 33, 'The Study (Stormester Season 2)', 'study', NULL, NULL, NULL, NULL, NULL),
