(46, 36, 'The Study (Stormester Season 7 - One More Chance)', 'study', NULL, NULL, NULL, NULL, NULL),
(47, 63, 'The Study (Stormester Season 8 - )', 'study', NULL, NULL, NULL, NULL, NULL),
(48, 32, 'The Garden (Stormester Season 1)', 'garden', '048_the_garden_stormester_i.jpg', '048_the_garden_stormester_i_thumb.jpg', '048_the_garden_stormester_i_2.jpg', 'The Stormester house used for the production of the first season of the show has gardens at both the front and rear, which connect through a gate at the side of the house.|The front garden is mostly lawn, with a paved pathway leading from the front gate of the house to a small patio area in front of the steps.|The back garden is also mostly lawn, with a hedge down one side and a wooden fence along the other side, and the rear. There is also <a href=\"/space.php?id=99\">a shed</a> and <a href=\"/space.php?id=98\">a playhouse</a> in the back garden, and it backs onto the <a href=\"/location.php?id=84\">Charlottenlund Racetrack</a>.', 'The front garden is first seen in the \'<a href=\"/task.php?id=571\">Keep the basketball on the treadmill</a>\' task, in the second episode of season 1.|The back garden is first seen in the \'<a href=\"/task.php?id=580\">Get the potato into the hole</a>\' task, in the third episode of season 1.'),
