--
-- Table structure for table `location_spaces`
--

CREATE TABLE `location_spaces` (
  `id` smallint(3) UNSIGNED NOT NULL COMMENT 'Unique identifier.',
  `parent_id` smallint(3) UNSIGNED DEFAULT NULL COMMENT 'ID of parent location.',
  `name` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Name of space.',
  `category` enum('lab','study','living room','kitchen','garden','shed','caravan','dome','driveway','patio','hallway','bathroom','gazebo','playhouse','porch','balcony','pool','barn','dining room','basement','outhouse') COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Space category',
  `primary_photo` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Primary photo URL.',
  `primary_photo_thumbnail` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Smaller version of primary photo.',
  `secondary_photo` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Secondary photo URL.',
  `description` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Description of space (use pipe characters for paragraph breaks).',
  `first_appearance` varchar(512) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Description of the location''s first appearance on the show (use pipe characters for paragraph breaks).'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

